import{_ as a,o as t,c as o,a3 as s}from"./chunks/framework.Ki30n65y.js";const r="/depgate/screenshots/package-check.png",n="/depgate/screenshots/package-check-blocked.png",u=JSON.parse('{"title":"Check a package","description":"","frontmatter":{},"headers":[],"relativePath":"developers/package-check.md","filePath":"developers/package-check.md"}'),i={name:"developers/package-check.md"};function c(l,e,h,d,p,k){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="check-a-package" tabindex="-1">Check a package <a class="header-anchor" href="#check-a-package" aria-label="Permalink to &quot;Check a package&quot;">​</a></h1><p><strong>Package check</strong> tells you, before you install, which versions of a package you can use, which are blocked and why, and the newest version that is allowed. It uses the same policies and data as a real download, so the answer matches what your package manager will get. A check downloads nothing and never counts as a block; it is noted in the Audit Log.</p><p>Every signed-in user can use it. Open <strong>Package check</strong> in the sidebar.</p><h2 id="check-a-package-1" tabindex="-1">Check a package <a class="header-anchor" href="#check-a-package-1" aria-label="Permalink to &quot;Check a package&quot;">​</a></h2><ol><li>Choose the <strong>Ecosystem</strong>.</li><li>Type the <strong>Package</strong> name. Use <code>groupId:artifactId</code> for Maven, <code>vendor/package</code> for Composer, and the module path for Go.</li><li>Optionally choose the <strong>Repository</strong>. Use the same repository as your package manager, because some policies apply only to some repositories.</li><li>Optionally type a <strong>Version</strong> to check a specific one, even an old one.</li><li>Choose <strong>Check</strong>, or press Enter.</li></ol><p><img src="'+r+'" alt="Package check results for lodash"></p><p>Your last five checks appear as chips under the search bar, so you can repeat them with one click.</p><h2 id="read-the-results" tabindex="-1">Read the results <a class="header-anchor" href="#read-the-results" aria-label="Permalink to &quot;Read the results&quot;">​</a></h2><ul><li><strong>Recommended version</strong>: The newest allowed stable version, with its license, its status, the policy that decided it and an install command you can copy. The status tells you when it is only allowed by an exception, or when a policy in monitor mode would block it once enforced. If no stable version is allowed, the newest allowed version of any kind, labelled with its type. Licenses can change between versions, so check the recommended version&#39;s license before you upgrade.</li><li><strong>Version you asked for</strong>: When you enter a version, it appears next to the recommendation with its license, its status, the policy that decided it and the reasons. If it is blocked, you can request a waiver from here.</li><li><strong>Version table</strong>: The most recent versions, newest first, with release date, release type (Stable, Pre-release and so on), status and reason. Use <strong>Allowed only</strong>, <strong>Hide pre-releases</strong> and the version filter to narrow the list. <strong>Load more</strong> checks the next ten versions.</li></ul><p>Above the results, the result header says when the check ran, which registry it was <strong>Checked against</strong>, the order a virtual repository <strong>Searched in</strong>, and which remote the package is <strong>Served by</strong>.</p><p><img src="'+n+'" alt="Package check for a blocked version, with the recommended alternative"></p><h3 id="project-health" tabindex="-1">Project health <a class="header-anchor" href="#project-health" aria-label="Permalink to &quot;Project health&quot;">​</a></h3><p>For a public package whose source repository is on GitHub or GitLab, a <strong>Project health</strong> card shows the package&#39;s <a href="https://scorecard.dev" target="_blank" rel="noreferrer">OpenSSF Scorecard</a> result: the overall score out of 10, the repository, whether the package declared that repository itself or DepGate found it on deps.dev, and when it was last scanned. Choose <strong>Details</strong> to see the score of each check, such as Code-Review or Dangerous-Workflow. When there is no result, the card says why: the package declares no repository, Scorecard has not scanned it, or Scorecard could not be reached. This is the same data a <a href="/depgate/admin/policy-rules#project-health">Project health policy</a> uses.</p><h3 id="statuses" tabindex="-1">Statuses <a class="header-anchor" href="#statuses" aria-label="Permalink to &quot;Statuses&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><strong>Allowed</strong></td><td>No policy blocks this version, or an exception covers it.</td></tr><tr><td><strong>Allowed · exception</strong></td><td>Blocked by a policy, but an active exception lets it through until the date shown.</td></tr><tr><td><strong>Allowed · would be blocked by &quot;…&quot; (monitoring)</strong></td><td>Allowed today, but a policy in monitor mode matches it. It will be blocked when that policy is enforced. Choose another version if you can.</td></tr><tr><td><strong>Allowed · vulnerability data unavailable</strong></td><td>Allowed only because vulnerability data could not be loaded. It is never recommended.</td></tr><tr><td><strong>Blocked</strong></td><td>A policy or the malware list blocks it. The reason column says which, and why.</td></tr><tr><td><strong>Not checked · timed out</strong></td><td>The check ran out of time before reaching this version. Check again; the second check is faster.</td></tr></tbody></table><p>A version blocked only because it is too new shows when it can be checked again. It may still be blocked by another policy then.</p><h3 id="vulnerabilities" tabindex="-1">Vulnerabilities <a class="header-anchor" href="#vulnerabilities" aria-label="Permalink to &quot;Vulnerabilities&quot;">​</a></h3><p>Each vulnerability appears as a chip with its ID, its CVSS version and score, and its EPSS exploit likelihood, for example <code>CVE-2021-23337 · CVSS 3.1 8.1 · EPSS 21.3 % · 97th</code>. Red chips are rated High or Critical. CVE IDs link to the advisory on <a href="https://osv.dev" target="_blank" rel="noreferrer">osv.dev</a>.</p><h3 id="whole-package-banners" tabindex="-1">Whole-package banners <a class="header-anchor" href="#whole-package-banners" aria-label="Permalink to &quot;Whole-package banners&quot;">​</a></h3><ul><li><strong>Malicious package</strong>: the package is on the malware list. No version is allowed and waivers are not offered.</li><li><strong>Blocked by policy</strong>: a policy blocks every version of this package.</li></ul><h2 id="share-or-bookmark-a-check" tabindex="-1">Share or bookmark a check <a class="header-anchor" href="#share-or-bookmark-a-check" aria-label="Permalink to &quot;Share or bookmark a check&quot;">​</a></h2><p>The address of the page contains the check, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://depgate.example.com/package-check?ecosystem=npm&amp;package=lodash&amp;version=4.17.20&amp;repository=default</span></span></code></pre></div><p>Opening it fills in the form and runs the check. When a download is blocked, the 403 response includes this link as <code>checkUrl</code>.</p><h2 id="if-you-need-a-blocked-version" tabindex="-1">If you need a blocked version <a class="header-anchor" href="#if-you-need-a-blocked-version" aria-label="Permalink to &quot;If you need a blocked version&quot;">​</a></h2><ul><li><strong>Users</strong> choose <strong>Request waiver</strong> on the blocked row. The waiver form opens with the package and version filled in. See <a href="./waiver-requests">Request a waiver</a>.</li><li><strong>Security</strong> users choose <strong>Add exception</strong> instead, which creates the exception directly.</li></ul><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>A check evaluates the newest 10 versions, the version you asked for, and the version a plain install would pick.</li><li>Each user can run 30 checks per minute.</li><li>A check stops after 10 seconds and returns what it has.</li></ul><p>Pipelines can call the same check through the API (<code>POST /api/package-check</code>) to fail a build when a pinned version is not allowed. See the <a href="/depgate/reference/api">REST API</a>.</p>',29)])])}const b=a(i,[["render",c]]);export{u as __pageData,b as default};
